import subprocess, tempfile, pathlib, os, shutil, time, urllib.request, json, sys, signal, threading

tmp = tempfile.mkdtemp()
shutil.copytree("/workspace/example", tmp+"/collection", dirs_exist_ok=True)
# ensure no db
try:
    os.remove(tmp+"/collection/hashcards.db")
except:
    pass
port=18083
proc = subprocess.Popen(["/workspace/executable","drill", tmp+"/collection", "--host","127.0.0.1","--port",str(port),"--open-browser","false"], stdout=subprocess.PIPE, stderr=subprocess.PIPE, text=True, bufsize=1)

def read_pipe(pipe, name):
    try:
        for line in pipe:
            print(f"[{name}] {line}", end='')
    except:
        pass

t1=threading.Thread(target=read_pipe, args=(proc.stdout,"OUT"), daemon=True)
t2=threading.Thread(target=read_pipe, args=(proc.stderr,"ERR"), daemon=True)
t1.start(); t2.start()

time.sleep(1)
print("poll", proc.poll())
# fetch
try:
    with urllib.request.urlopen(f"http://127.0.0.1:{port}/", timeout=3) as resp:
        data=resp.read().decode()
        print("ROOT len", len(data))
        print(data[:5000])
except Exception as e:
    print("root fetch fail", e)

# Try /api or /static list? Try guessing endpoints
endpoints = ["/", "/api/cards", "/api/stats", "/api/decks", "/cards", "/api", "/static", "/__docs__"]
for ep in endpoints:
    try:
        with urllib.request.urlopen(f"http://127.0.0.1:{port}{ep}", timeout=2) as resp:
            d=resp.read()
            print(f"{ep} => {len(d)} {d[:500]}")
    except Exception as e:
        print(f"{ep} fail {e}")

# Try to inspect HTML for JS files
try:
    with urllib.request.urlopen(f"http://127.0.0.1:{port}/", timeout=2) as resp:
        html=resp.read().decode()
        # find src/href
        import re
        for m in re.findall(r'src="([^"]+)"|href="([^"]+)"', html):
            print("asset", m)
            for url in m:
                if url:
                    try:
                        with urllib.request.urlopen(f"http://127.0.0.1:{port}{url}" if url.startswith("/") else f"http://127.0.0.1:{port}/{url}", timeout=2) as r2:
                            d2=r2.read()
                            print(f"  asset {url} len {len(d2)} preview {d2[:1000]}")
                    except Exception as e2:
                        print(f"  asset fetch {url} fail {e2}")
except Exception as e:
    print("html parse fail", e)

proc.terminate()
try:
    proc.wait(timeout=2)
except:
    proc.kill()
shutil.rmtree(tmp)
PY
