        match block {
            RawBlock::Basic { start_idx, q_first, q_extra, a_first, a_extra, .. } => {
                // Build question: q_first + "\n" + q_extra joined, with q_extra already trailing trimmed, but q_first trimmed both.
                // Actually q_extra lines are already trailing trimmed, but we need to join with "\n"
                // For question, we have q_first (already trimmed both) plus q_extra (each trailing trimmed, leading preserved)
                let mut q_lines: Vec<String> = Vec::new();
                q_lines.push(q_first.clone());
