                    }

                    // Check if current card's family is buried
                    {
                        let buried = state.buried_families.lock().unwrap();
                        // Need to handle bury siblings: if card's family is in buried, skip it
                        // For simplicity, we will skip in GET handler by advancing idx until unburied
                        // But we need mutable access, so we will handle skipping in a loop
                    }

                    // For simplicity, we will handle bury skipping here with mutable locks
                    // We need to drop immutable borrow first
