                        let html = format!(r#"<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>hashcards</title><link rel="stylesheet" href="/katex/katex.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css"><script defer src="/katex/katex.js"></script><script defer src="/katex/mhchem.js"></script><script defer src="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js"></script><link rel="stylesheet" href="/style.css"><style>.card-content {{ opacity: 0; }}</style><noscript><style>.card-content {{ opacity: 1; }}</style></noscript></head><body><div class="finished"><h1>Session Completed 🎉</h1><div class="summary">Reviewed {reviewed} cards in {duration} seconds.</div><h2>Session Stats</h2><div class="stats"><table><tbody><tr><td class="key">Total Cards</td><td class="val">{total}</td></tr><tr><td class="key">Cards Reviewed</td><td class="val">{reviewed}</td></tr><tr><td class="key">Started</td><td class="val">{started}</td></tr><tr><td class="key">Finished</td><td class="val">{ended}</td></tr><tr><td class="key">Duration (seconds)</td><td class="val">{duration}</td></tr><tr><td class="key">Pace (s/card)</td><td class="val">{pace:.2}</td></tr></tbody></table></div><div class="shutdown-container"><form action="/" method="post"><input class="shutdown-button" id="shutdown" type="submit" name="action" value="Shutdown" title="Shut down the server"></form></div></div><script src="/script.js"></script></body></html>"#,
                            total=total, reviewed=reviewed, started=started.format("%Y-%m-%d %H:%M:%S"), ended=ended.format("%Y-%m-%d %H:%M:%S"), duration=duration, pace=pace
                        );
                        return Html(html);
