                async fn root_post(State(state): State<Arc<AppState>>, Form(form): Form<ActionForm>) -> impl IntoResponse {
                    let action = form.action;
                    // Handle actions
                    match action.as_str() {
                        "Reveal" => {
                            *state.revealed.lock().unwrap() = true;
                        },
                        "Undo" => {
                            // Undo last review: need to pop last review and restore card idx and buried families?
                            // For simplicity, we will pop last review and decrement idx if possible
                            let mut reviews = state.reviews.lock().unwrap();
                            if let Some((hash, _, _, _, _, _, _)) = reviews.pop() {
                                // Remove from buried families if this card's family was added due to this review?
                                // For simplicity, if bury_siblings true, we need to remove family of undone card from buried set if it was added
                                // But we don't track which family was buried when. We'll just clear buried families and re-add for all remaining reviews
                                let mut buried = state.buried_families.lock().unwrap();
                                buried.clear();
                                // Re-add families for remaining reviews
                                let cards = state.cards.lock().unwrap();
                                for (rev_hash, _, _, _, _, _, _) in reviews.iter() {
                                    // Find card with this hash
                                    for card in cards.iter() {
                                        if card.parsed.hash == *rev_hash {
                                            if let Some(ref fam) = card.parsed.family_hash {
                                                buried.insert(fam.clone());
                                            }
                                        }
                                    }
                                }
                            }
                            // Decrement idx
                            let mut idx = state.current_idx.lock().unwrap();
                            if *idx > 0 {
                                *idx -= 1;
                            }
                            *state.revealed.lock().unwrap() = false;
                        },
                        "Forgot" | "Hard" | "Good" | "Easy" => {
                            // Grade current card
                            let mut cards = state.cards.lock().unwrap();
                            let mut idx = state.current_idx.lock().unwrap();
                            if *idx < cards.len() {
                                let card = &mut cards[*idx];
                                // Compute new stability, difficulty, interval
                                let now = Local::now().naive_local();
                                let today = Local::now().naive_local().date();
                                let t_days = if let Some(last) = card.last_reviewed {
                                    (now.date() - last.date()).num_days() as f64
                                } else {
