                                        let mut buried = state.buried_families.lock().unwrap();
                                        buried.insert(fam.clone());
                                    }
                                }

                                // Add to reviews
                                let mut reviews = state.reviews.lock().unwrap();
                                reviews.push((card.parsed.hash.clone(), action.clone(), new_stab, new_diff, interval_raw, interval_days, due_date.format("%Y-%m-%d").to_string()));

                                // Advance idx
                                *idx += 1;
                                *state.revealed.lock().unwrap() = false;
                            }
                        },
