                        review_count: 0,
                        last_reviewed: None,
                    });
                }
            }

            // Filter by from_deck if specified
            if let Some(ref deck_filter) = from_deck {
                card_states.retain(|cs| cs.parsed.deck_name == *deck_filter);
            }

            // Determine which cards are due: If review_count==0 (new) or due_date <= today
