                                row.get::<_, Option<String>>(1)?,
                                row.get::<_, Option<f64>>(2)?,
                                row.get::<_, Option<f64>>(3)?,
                                row.get::<_, Option<f64>>(4)?,
                                row.get::<_, Option<i64>>(5)?,
                                row.get::<_, Option<String>>(6)?,
                                row.get::<_, i64>(7)?,
                            ))
                        }) {
                            for r in rows {
                                if let Ok((hash, last_rev, stab, diff, int_raw, int_days, due, rev_cnt)) = r {
                                    if rev_cnt>0 {
                                        performance_map.insert(hash, Performance {
                                            lastReviewedAt: last_rev,
                                            stability: stab,
                                            difficulty: diff,
                                            intervalRaw: int_raw,
                                            intervalDays: int_days,
                                            dueDate: due,
                                            reviewCount: Some(rev_cnt),
                                        });
                                    }
                                }
                            }
                        }
                    }

                    // Load sessions
                    if let Ok(mut stmt) = conn.prepare("SELECT session_id, started_at, ended_at FROM sessions ORDER BY session_id") {
                        if let Ok(sess_rows) = stmt.query_map([], |row| {
                            Ok((
                                row.get::<_, i64>(0)?,
                                row.get::<_, String>(1)?,
                                row.get::<_, String>(2)?,
                            ))
                        }) {
                            for sess_res in sess_rows {
                                if let Ok((sid, started, ended)) = sess_res {
                                    // Load reviews for this session
                                    let mut revs: Vec<ReviewExport> = Vec::new();
                                    if let Ok(mut rev_stmt) = conn.prepare("SELECT review_id, card_hash, reviewed_at, grade, stability, difficulty, interval_raw, interval_days, due_date FROM reviews WHERE session_id=?1 ORDER BY review_id") {
                                        if let Ok(rev_rows) = rev_stmt.query_map(params![sid], |row| {
                                            Ok(ReviewExport {
                                                reviewId: row.get(0)?,
                                                hash: row.get(1)?,
                                                reviewedAt: row.get(2)?,
                                                grade: row.get::<_, String>(3)?.to_lowercase(),
                                                stability: row.get(4)?,
                                                difficulty: row.get(5)?,
                                                intervalRaw: row.get(6)?,
                                                intervalDays: row.get(7)?,
                                                dueDate: row.get(8)?,
                                            })
                                        }) {
                                            for rev in rev_rows {
                                                if let Ok(r) = rev {
                                                    revs.push(r);
                                                }
                                            }
                                        }
                                    }
                                    sessions.push(SessionExport {
                                        sessionId: sid,
                                        startedAt: started,
                                        endedAt: ended,
                                        reviews: revs,
                                    });
                                }
                            }
                        }
                    }
                }
            }

            // Build export cards
            let mut export_cards: Vec<ExportCard> = Vec::new();
            for pc in parsed {
                let perf = performance_map.get(&pc.hash).cloned();
                let content = match pc.content_internal {
                    CardContentInternal::Basic { question, answer } => {
                        ExportCardContent {
                            basic: Some(BasicContent { question, answer }),
                            cloze: None,
                        }
                    },
                    CardContentInternal::Cloze { text, start, end, .. } => {
                        ExportCardContent {
                            basic: None,
                            cloze: Some(ClozeContent { text, start, end }),
                        }
                    },
                };
                export_cards.push(ExportCard {
                    hash: pc.hash,
                    familyHash: pc.family_hash,
                    deckName: pc.deck_name,
                    location: pc.location,
                    content,
                    performance: perf,
                });
            }

            let output_data = ExportOutput {
                cards: export_cards,
                sessions,
            };

            let json_str = serde_json::to_string_pretty(&output_data).unwrap();

            if let Some(out_path) = output {
                std::fs::write(out_path, json_str)?;
            } else {
                println!("{}", json_str);
            }

            Ok(())
        },
    }
}

fn markdown_to_html(md: &str) -> String {
    // Use pulldown-cmark to render markdown to HTML
    // For simplicity, we will use pulldown-cmark

    let mut html_output = String::new();
    let parser = pulldown_cmark::Parser::new(md);
    pulldown_cmark::html::push_html(&mut html_output, parser);
    // The original binary's rich-text output seems to be like <p>...</p>\n
    // We will keep as is but trim?
    html_output
}

fn compute_fsrs(stability: Option<f64>, difficulty: Option<f64>, t_days: f64, grade_str: &str) -> (f64, f64, f64, i64, NaiveDate) {
    // Map grade string to rating 1..4
    let rating = match grade_str.to_lowercase().as_str() {
        "forgot" => 1,
        "hard" => 2,
        "good" => 3,
        "easy" => 4,
        _ => 3,
    };

    // Initial stability and difficulty if None
    let (mut new_stab, mut new_diff) = if stability.is_none() || difficulty.is_none() {
        // First review
        let stab = match rating {
            1 => W[0],
            2 => W[1],
            3 => W[2],
            4 => W[3],
            _ => W[2],
        };
        let diff = W[4] - (W[5] * (rating as f64 -1.0)).exp() + 1.0;
        (stab, diff)
    } else {
        // Subsequent review
        let S = stability.unwrap();
        let D = difficulty.unwrap();
        let R = {
            // R = (1 + 19/81 * t / S)^-0.5
            let factor = 19.0/81.0;
            (1.0 + factor * t_days / S).powf(-0.5)
        };

        // Stability
        let new_stab = if rating == 1 {
            // Forgot
            W[11] * D.powf(-W[12]) * ((S+1.0).powf(W[13]) -1.0) * ((1.0-R)*W[14]).exp()
        } else {
            let mut A = (W[8]).exp() * (11.0 - D) * S.powf(-W[9]);
            if rating == 2 {
                A *= W[15];
            } else if rating == 4 {
                A *= W[16];
            }
            S * (1.0 + A * ((1.0-R)*W[10]).exp() -1.0)
            // Actually formula is S * (1 + A*(exp((1-R)*w10)-1))
        };

        // Difficulty: exact fit we found
        // D' = a*D + b*D*(G-3) + c*(G-3) + d
        // where a=0.9954, b=0.16152024, c=-1.6152024, d=0.01483270731112081
        let a = 0.9953999999999978;
        let b = 0.16152024;
        let c = -1.6152024;
        let d = 0.01483270731112081;
        let G = rating as f64;
        let new_diff = a*D + b*D*(G-3.0) + c*(G-3.0) + d;
        // Clamp difficulty to [1,10]
        let new_diff = new_diff.max(1.0).min(10.0);

        (new_stab, new_diff)
    };

    // For new cards, interval_raw = new_stab
    // For subsequent, interval_raw = new_stab as well? Observed earlier interval_raw = stability for all cases we checked (after first and second)
    let interval_raw = new_stab;
    let interval_days = (interval_raw.round() as i64).max(1);
    let due_date = Local::now().naive_local().date() + Duration::days(interval_days as i64);

    // For difficulty, we already computed

    (new_stab, new_diff, interval_raw, interval_days, due_date)
}

