#[derive(Debug)]
enum ParseError {
    Message(String, String, usize),
}

#[derive(Debug, Clone)]
enum RawBlock {
    Basic { start_idx: usize, q_first: String, q_extra: Vec<String>, a_first: String, a_extra: Vec<String> },
    Cloze { start_idx: usize, c_first: String, c_extra: Vec<String> },
}

impl RawBlock {
    fn start_idx(&self) -> usize {
        match self {
            RawBlock::Basic { start_idx, .. } => *start_idx,
            RawBlock::Cloze { start_idx, .. } => *start_idx,
        }
    }
}

#[derive(Debug, Clone)]
enum RawCard {
    Basic { location: Location, question: String, answer: String },
    ClozeInstance { location: Location, text: String, start: usize, end: usize, word: String },
}

fn parse_markdown_file(file_path: &Path, content: &str) -> Result<Vec<RawCard>, ParseError> {
    let lines: Vec<&str> = content.lines().collect();

    #[derive(Debug)]
    enum State {
        Idle,
        InQuestion { start_idx: usize, q_first: String, q_extra: Vec<String> },
        InAnswer { start_idx: usize, q_first: String, q_extra: Vec<String>, a_first: String, a_extra: Vec<String> },
        InCloze { start_idx: usize, c_first: String, c_extra: Vec<String> },
    }

    fn trim_trailing(s: &str) -> &str {
        s.trim_end_matches(|c| c == ' ' || c == '\t' || c == '\r')
    }
    fn trim_both(s: &str) -> String {
        s.trim_matches(|c| c == ' ' || c == '\t' || c == '\r').to_string()
    }

    let mut state = State::Idle;
    let mut raw_blocks: Vec<RawBlock> = Vec::new();
    let mut i = 0;
    while i < lines.len() {
        let line = lines[i];
        if line.starts_with("Q:") {
            let rest = &line[2..];
            match state {
                State::Idle => {
                    let q_first = trim_both(rest);
                    state = State::InQuestion { start_idx: i, q_first, q_extra: Vec::new() };
                },
                State::InQuestion { .. } => {
                    return Err(ParseError::Message("New question without answer.".to_string(), file_path.to_string_lossy().to_string(), i+1));
                },
                State::InAnswer { start_idx, q_first, q_extra, a_first, a_extra } => {
                    raw_blocks.push(RawBlock::Basic { start_idx, q_first, q_extra, a_first, a_extra });
                    let q_first = trim_both(rest);
                    state = State::InQuestion { start_idx: i, q_first, q_extra: Vec::new() };
                },
                State::InCloze { start_idx, c_first, c_extra } => {
                    raw_blocks.push(RawBlock::Cloze { start_idx, c_first, c_extra });
                    let q_first = trim_both(rest);
                    state = State::InQuestion { start_idx: i, q_first, q_extra: Vec::new() };
                },
            }
        } else if line.starts_with("A:") {
            let rest = &line[2..];
            match state {
                State::Idle => {
                    return Err(ParseError::Message("Found answer tag without a question.".to_string(), file_path.to_string_lossy().to_string(), i+1));
                },
                State::InQuestion { start_idx, q_first, q_extra } => {
                    let a_first = trim_both(rest);
                    state = State::InAnswer { start_idx, q_first, q_extra, a_first, a_extra: Vec::new() };
                },
                State::InAnswer { .. } => {
                    return Err(ParseError::Message("Found answer tag while reading an answer.".to_string(), file_path.to_string_lossy().to_string(), i+1));
                },
                State::InCloze { .. } => {
                    return Err(ParseError::Message("Found answer tag while reading a cloze card.".to_string(), file_path.to_string_lossy().to_string(), i+1));
                },
            }
        } else if line.starts_with("C:") {
            let rest = &line[2..];
            match state {
                State::Idle => {
                    let c_first = trim_both(rest);
                    state = State::InCloze { start_idx: i, c_first, c_extra: Vec::new() };
                },
                State::InQuestion { .. } => {
                    return Err(ParseError::Message("Found cloze tag while reading a question.".to_string(), file_path.to_string_lossy().to_string(), i+1));
                },
                State::InAnswer { start_idx, q_first, q_extra, a_first, a_extra } => {
                    raw_blocks.push(RawBlock::Basic { start_idx, q_first, q_extra, a_first, a_extra });
                    let c_first = trim_both(rest);
                    state = State::InCloze { start_idx: i, c_first, c_extra: Vec::new() };
                },
                State::InCloze { start_idx, c_first, c_extra } => {
                    raw_blocks.push(RawBlock::Cloze { start_idx, c_first, c_extra });
                    let c_first = trim_both(rest);
                    state = State::InCloze { start_idx: i, c_first, c_extra: Vec::new() };
                },
            }
        } else {
            match &mut state {
                State::Idle => {},
                State::InQuestion { q_extra, .. } => {
                    q_extra.push(trim_trailing(line).to_string());
                },
                State::InAnswer { a_extra, .. } => {
                    a_extra.push(trim_trailing(line).to_string());
                },
                State::InCloze { c_extra, .. } => {
                    c_extra.push(trim_trailing(line).to_string());
                },
            }
        }
        i+=1;
    }

    match state {
        State::Idle => {},
        State::InQuestion { .. } => {
            return Err(ParseError::Message("File ended while reading a question without an answer.".to_string(), file_path.to_string_lossy().to_string(), lines.len()));
        },
        State::InAnswer { start_idx, q_first, q_extra, a_first, a_extra } => {
            raw_blocks.push(RawBlock::Basic { start_idx, q_first, q_extra, a_first, a_extra });
        },
        State::InCloze { start_idx, c_first, c_extra } => {
            raw_blocks.push(RawBlock::Cloze { start_idx, c_first, c_extra });
        },
    }

    let mut raw_cards: Vec<RawCard> = Vec::new();
    for (idx, block) in raw_blocks.iter().enumerate() {
        let next_start = if idx+1 < raw_blocks.len() {
            raw_blocks[idx+1].start_idx()
        } else {
            if lines.is_empty() { 0 } else { lines.len() -1 }
        };
        match block {
            RawBlock::Basic { start_idx, q_first, q_extra, a_first, a_extra } => {
                let mut q_lines = Vec::new();
                q_lines.push(q_first.clone());
                q_lines.extend(q_extra.clone());
                let question = q_lines.join("\n").trim().to_string();
                let mut a_lines = Vec::new();
                a_lines.push(a_first.clone());
                a_lines.extend(a_extra.clone());
                let answer = a_lines.join("\n").trim().to_string();
                let location = Location {
                    filePath: file_path.to_string_lossy().to_string(),
                    lineStart: *start_idx,
                    lineEnd: next_start,
                };
                raw_cards.push(RawCard::Basic { location, question, answer });
            },
            RawBlock::Cloze { start_idx, c_first, c_extra } => {
                let mut c_lines = Vec::new();
                c_lines.push(c_first.clone());
                c_lines.extend(c_extra.clone());
                let raw_content = c_lines.join("\n").trim().to_string();
                let chars: Vec<char> = raw_content.chars().collect();
                let mut stack: Vec<usize> = Vec::new();
                let mut pairs: Vec<(usize, usize)> = Vec::new();
                for (char_idx, ch) in chars.iter().enumerate() {
                    if *ch == '[' {
                        stack.push(char_idx);
                    } else if *ch == ']' {
                        if let Some(l) = stack.pop() {
                            pairs.push((l, char_idx));
                        }
                    }
                }
                let mut valid_pairs: Vec<(usize, usize)> = Vec::new();
                for (l,r) in pairs {
                    let interior = &chars[l+1..r];
                    if interior.iter().any(|c| *c=='[' || *c==']') {
                        continue;
                    }
                    valid_pairs.push((l,r));
                }
                if valid_pairs.is_empty() {
                    return Err(ParseError::Message("Cloze card must contain at least one cloze deletion.".to_string(), file_path.to_string_lossy().to_string(), start_idx+1));
                }
                let stripped: String = raw_content.chars().filter(|c| *c!='[' && *c!=']').collect();
                let stripped_trimmed = stripped.trim().to_string();
                let leading_ws_len = stripped.len() - stripped.trim_start().len();
                let raw_chars = raw_content.chars().collect::<Vec<char>>();
                for (l,r) in valid_pairs {
                    let word: String = raw_chars[l+1..r].iter().collect();
                    let mut count = 0;
                    for idx in 0..l {
                        let ch = raw_chars[idx];
                        if ch!='[' && ch!=']' {
                            count+=1;
                        }
                    }
                    let start = if count >= leading_ws_len { count - leading_ws_len } else { 0 };
                    let end = if word.is_empty() { start } else { start + word.chars().count() -1 };
                    let location = Location {
                        filePath: file_path.to_string_lossy().to_string(),
                        lineStart: *start_idx,
                        lineEnd: next_start,
                    };
                    raw_cards.push(RawCard::ClozeInstance { location, text: stripped_trimmed.clone(), start, end, word });
                }
            },
        }
    }

    Ok(raw_cards)
}

fn collect_md_files(dir: &Path, out: &mut Vec<PathBuf>) -> Result<(), String> {
    let entries = std::fs::read_dir(dir).map_err(|_| "directory does not exist.".to_string())?;
    for entry in entries {
        let entry = entry.map_err(|e| format!("I/O error: {}", e))?;
        let path = entry.path();
        if path.is_dir() {
            collect_md_files(&path, out)?;
        } else if path.is_file() {
            if let Some(ext) = path.extension() {
                if ext == "md" {
                    out.push(path);
                }
            }
        }
    }
    Ok(())
}

fn parse_collection(dir: &Path) -> Result<Vec<ParsedCard>, String> {
    let mut files: Vec<PathBuf> = Vec::new();
    collect_md_files(dir, &mut files)?;
    let mut all_cards: Vec<ParsedCard> = Vec::new();
    for file_path in files {
        let content = std::fs::read_to_string(&file_path).map_err(|e| format!("I/O error: {}", e))?;
        let raw_cards = parse_markdown_file(&file_path, &content).map_err(|ParseError::Message(msg, fp, line)| {
            format!("Parse error: {}. Location: {}:{}", msg, fp, line)
        })?;
        for rc in raw_cards {
            match rc {
                RawCard::Basic { location, question, answer } => {
                    let deck_name = file_path.file_stem().unwrap().to_string_lossy().to_string();
                    let hash = hash_basic(&question, &answer);
                    all_cards.push(ParsedCard {
                        hash,
                        family_hash: None,
                        deck_name,
                        location,
                        content_internal: CardContentInternal::Basic { question, answer },
                    });
                },
                RawCard::ClozeInstance { location, text, start, end, word } => {
                    let deck_name = file_path.file_stem().unwrap().to_string_lossy().to_string();
                    let family_hash = hash_family(&text);
                    let card_hash = hash_cloze(&family_hash, start, end, &word);
                    all_cards.push(ParsedCard {
                        hash: card_hash,
                        family_hash: Some(family_hash),
                        deck_name,
                        location,
                        content_internal: CardContentInternal::Cloze { text, start, end, word },
                    });
                },
            }
        }
    }
    Ok(all_cards)
}

fn db_path(dir: &Path) -> PathBuf {
    dir.join("hashcards.db")
}

fn ensure_db(conn: &Connection) -> rusqlite::Result<()> {
    conn.execute(
        "CREATE TABLE IF NOT EXISTS cards (
            card_hash text primary key,
            added_at text not null,
            last_reviewed_at text,
            stability real,
            difficulty real,
            interval_raw real,
            interval_days integer,
            due_date text,
            review_count integer not null
        ) strict",
        [],
    )?;
    conn.execute(
        "CREATE TABLE IF NOT EXISTS sessions (
            session_id integer primary key,
            started_at text not null,
            ended_at text not null
        ) strict",
        [],
    )?;
    conn.execute(
        "CREATE TABLE IF NOT EXISTS reviews (
            review_id integer primary key,
            session_id integer not null references sessions (session_id) on update cascade on delete cascade,
            card_hash text not null references cards (card_hash) on update cascade on delete cascade,
            reviewed_at text not null,
            grade text not null,
            stability real not null,
            difficulty real not null,
            interval_raw real not null,
            interval_days integer not null,
            due_date text not null
        ) strict",
        [],
    )?;
    Ok(())
}

fn parse_chrono(s: &str) -> Option<NaiveDateTime> {
    if let Ok(dt) = NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S%.3f") {
        return Some(dt);
    }
    if let Ok(dt) = NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S%.6f") {
        return Some(dt);
    }
    if let Ok(dt) = NaiveDateTime::parse_from_str(s, "%Y-%m-%dT%H:%M:%S") {
        return Some(dt);
    }
    None
}

fn count_tex_macros(dir: &Path) -> usize {
    let macros_path = dir.join("macros.tex");
    if !macros_path.exists() {
        return 0;
    }
    let content = std::fs::read_to_string(&macros_path).unwrap_or_default();
    let mut count = 0;
    for line in content.lines() {
        if !line.contains(' ') {
            continue;
        }
        let trimmed = line.trim_start();
        if trimmed.starts_with('%') {
            continue;
        }
        count+=1;
    }
    count
}

fn check_media(dir: &Path, cards: &[ParsedCard]) -> Result<(), String> {
    let re = regex::Regex::new(r"!\[[^\]]*\]\(([^)]+)\)").unwrap();
    let mut missing: Vec<String> = Vec::new();
    for card in cards {
        let texts: Vec<String> = match &card.content_internal {
            CardContentInternal::Basic { question, answer } => vec![question.clone(), answer.clone()],
            CardContentInternal::Cloze { text, .. } => vec![text.clone()],
        };
        for txt in texts {
            for cap in re.captures_iter(&txt) {
                let path_str = cap[1].to_string();
                let resolved: PathBuf;
                if path_str.starts_with("@/") {
                    let inner = &path_str[2..];
                    resolved = dir.join(inner);
                } else {
                    let deck_file_dir = Path::new(&card.location.filePath).parent().unwrap_or(dir);
                    resolved = deck_file_dir.join(&path_str);
                }
                // For check, need to canonicalize and ensure inside collection? Original check follows symlinks but only if inside collection?
                // For simplicity, check existence, but also check if resolved is inside dir via canonicalize
                let exists = resolved.exists();
                // Additional check: if symlink points outside collection, treat as missing? We observed symlink to parent fails.
                // So we should canonicalize and check if starts with dir
                let inside = if let Ok(canon) = std::fs::canonicalize(&resolved) {
                    if let Ok(dir_canon) = std::fs::canonicalize(dir) {
                        canon.starts_with(dir_canon)
                    } else {
                        true
                    }
                } else {
                    // If canonicalize fails, file doesn't exist, already missing
                    false
                };
                if !exists || !inside {
                    missing.push(format!("{} (referenced in {}:{})", path_str, card.location.filePath, card.location.lineStart));
                }
            }
        }
    }
    if !missing.is_empty() {
        let mut msg = String::from("Missing media files referenced in cards:\n");
        for m in missing {
            msg.push_str(&format!("  - {}\n", m));
        }
        return Err(msg.trim_end().to_string());
    }
    Ok(())
}

fn markdown_to_html(md: &str) -> String {
