fn compute_fsrs(stability: Option<f64>, difficulty: Option<f64>, t_days: f64, grade_str: &str) -> (f64, f64, f64, i64, NaiveDate) {
    let rating = match grade_str.to_lowercase().as_str() {
        "forgot" => 1,
        "hard" => 2,
        "good" => 3,
        "easy" => 4,
        _ => 3,
    };
    let (new_stab, new_diff) = if stability.is_none() || difficulty.is_none() {
        let stab = match rating {
            1 => W[0],
            2 => W[1],
            3 => W[2],
            4 => W[3],
            _ => W[2],
        };
        let diff = W[4] - (W[5] * (rating as f64 -1.0)).exp() + 1.0;
        (stab, diff)
    } else {
        let S = stability.unwrap();
        let D = difficulty.unwrap();
        let R = {
            let factor = 19.0/81.0;
            (1.0 + factor * t_days / S).powf(-0.5)
        };
        let new_stab = if rating == 1 {
            W[11] * D.powf(-W[12]) * ((S+1.0).powf(W[13]) -1.0) * ((1.0-R)*W[14]).exp()
        } else {
            let mut A = (W[8]).exp() * (11.0 - D) * S.powf(-W[9]);
            if rating == 2 {
                A *= W[15];
            } else if rating == 4 {
                A *= W[16];
            }
            S * (1.0 + A * (((1.0-R)*W[10]).exp() -1.0))
        };
        let a = 0.9953999999999978;
        let b = 0.16152024;
        let c = -1.6152024;
        let d = 0.01483270731112081;
        let G = rating as f64;
        let new_diff = a*D + b*D*(G-3.0) + c*(G-3.0) + d;
        let new_diff = new_diff.max(1.0).min(10.0);
        (new_stab, new_diff)
    };
    let interval_raw = new_stab;
    let interval_days = (interval_raw.round() as i64).max(1);
    let due_date = Local::now().naive_local().date() + Duration::days(interval_days);
    (new_stab, new_diff, interval_raw, interval_days, due_date)
}

#[tokio::main]
async fn main() -> Result<(), Box<dyn std::error::Error>> {
    let cli = Cli::parse();

    match cli.command {
        Commands::Drill { directory, card_limit, new_card_limit, host, port, from_deck, open_browser, answer_controls, bury_siblings } => {
            let collection_dir = directory.unwrap_or_else(|| std::env::current_dir().unwrap());
            if !collection_dir.exists() {
                eprintln!("hashcards: error: directory does not exist.");
                std::process::exit(1);
            }
            let parsed_cards = match parse_collection(&collection_dir) {
                Ok(c) => c,
                Err(e) => {
                    eprintln!("hashcards: error: {}", e);
                    std::process::exit(1);
                }
            };
            if let Err(e) = check_media(&collection_dir, &parsed_cards) {
                eprintln!("hashcards: error: {}", e);
                std::process::exit(1);
            }

            // DB
            let db_p = db_path(&collection_dir);
            let conn = Connection::open(&db_p)?;
            ensure_db(&conn)?;
            let now = Local::now().naive_local();
            let now_str = now.format("%Y-%m-%dT%H:%M:%S%.3f").to_string();
            for card in &parsed_cards {
                conn.execute(
                    "INSERT OR IGNORE INTO cards (card_hash, added_at, review_count) VALUES (?1, ?2, 0)",
                    params![card.hash, now_str],
                )?;
            }

            // Load states
            #[derive(Clone)]
            struct CardState {
                parsed: ParsedCard,
                stability: Option<f64>,
                difficulty: Option<f64>,
                interval_days: Option<i64>,
                due_date: Option<NaiveDate>,
                review_count: i64,
                last_reviewed: Option<NaiveDateTime>,
            }

            let mut card_states: Vec<CardState> = Vec::new();
            for pc in parsed_cards {
                let mut stmt = conn.prepare("SELECT stability, difficulty, interval_days, due_date, review_count, last_reviewed_at FROM cards WHERE card_hash=?1")?;
                let row = stmt.query_row(params![pc.hash], |row| {
                    Ok((
                        row.get::<_, Option<f64>>(0)?,
                        row.get::<_, Option<f64>>(1)?,
                        row.get::<_, Option<i64>>(2)?,
                        row.get::<_, Option<String>>(3)?,
                        row.get::<_, i64>(4)?,
                        row.get::<_, Option<String>>(5)?,
                    ))
                }).optional()?;
                if let Some((stab, diff, int_days, due_str, rev_cnt, last_rev_str)) = row {
                    let due_date = due_str.and_then(|s| NaiveDate::parse_from_str(&s, "%Y-%m-%d").ok());
                    let last_rev = last_rev_str.and_then(|s| parse_chrono(&s));
                    card_states.push(CardState {
                        parsed: pc,
                        stability: stab,
                        difficulty: diff,
                        interval_days: int_days,
                        due_date,
                        review_count: rev_cnt,
                        last_reviewed: last_rev,
                    });
                } else {
                    card_states.push(CardState {
                        parsed: pc,
                        stability: None,
                        difficulty: None,
                        interval_days: None,
                        due_date: None,
                        review_count: 0,
                        last_reviewed: None,
                    });
                }
            }

            if let Some(ref deck_filter) = from_deck {
                card_states.retain(|cs| cs.parsed.deck_name == *deck_filter);
            }

            let today = Local::now().naive_local().date();
            let mut due_cards: Vec<CardState> = Vec::new();
            let mut new_cards: Vec<CardState> = Vec::new();
            for cs in card_states {
                if cs.review_count == 0 {
                    new_cards.push(cs);
                } else if let Some(due) = cs.due_date {
                    if due <= today {
                        due_cards.push(cs);
                    }
                } else {
                    due_cards.push(cs);
                }
            }
            due_cards.sort_by(|a,b| {
                a.due_date.cmp(&b.due_date)
                    .then(a.parsed.deck_name.cmp(&b.parsed.deck_name))
                    .then(a.parsed.location.lineStart.cmp(&b.parsed.location.lineStart))
            });
            new_cards.sort_by(|a,b| {
                a.parsed.deck_name.cmp(&b.parsed.deck_name)
                    .then(a.parsed.location.lineStart.cmp(&b.parsed.location.lineStart))
            });
            let mut session_cards: Vec<CardState> = Vec::new();
            session_cards.extend(due_cards);
            if let Some(new_limit) = new_card_limit {
                new_cards.truncate(new_limit);
            }
            session_cards.extend(new_cards);
            if let Some(limit) = card_limit {
                session_cards.truncate(limit);
            }

            // DB session
            let started_at_str = now.format("%Y-%m-%dT%H:%M:%S%.3f").to_string();
            conn.execute(
                "INSERT INTO sessions (started_at, ended_at) VALUES (?1, ?2)",
                params![started_at_str, started_at_str],
            )?;
            let session_id = conn.last_insert_rowid();
            drop(conn);

            // App state
            struct AppState {
                cards: Mutex<Vec<CardState>>,
                current_idx: Mutex<usize>,
                revealed: Mutex<bool>,
                buried_families: Mutex<HashSet<String>>,
                session_id: i64,
                started_at: NaiveDateTime,
                bury_siblings: bool,
                answer_controls: String,
                reviews: Mutex<Vec<(String, String, f64, f64, f64, i64, String, String)>>, // hash, grade, stab, diff, int_raw, int_days, due_date, reviewed_at
                collection_dir: PathBuf,
            }

            let app_state = Arc::new(AppState {
                cards: Mutex::new(session_cards),
                current_idx: Mutex::new(0),
                revealed: Mutex::new(false),
                buried_families: Mutex::new(HashSet::new()),
                session_id,
                started_at: now,
                bury_siblings: bury_siblings.to_lowercase() == "true",
                answer_controls,
                reviews: Mutex::new(Vec::new()),
                collection_dir: collection_dir.clone(),
            });

            // Axum handlers
            use axum::{
                routing::{get, post},
                response::{Html, IntoResponse},
                Form,
                extract::{State, Path as AxumPath},
                http::{StatusCode, header},
            };
            use serde::Deserialize;

            #[derive(Deserialize)]
            struct ActionForm {
                action: String,
            }

            async fn root_get(State(state): State<Arc<AppState>>) -> impl IntoResponse {
                // Handle bury skipping
                {
                    let mut idx = state.current_idx.lock().unwrap();
                    let cards = state.cards.lock().unwrap();
                    let buried = state.buried_families.lock().unwrap();
                    while *idx < cards.len() {
                        if state.bury_siblings {
                            if let Some(ref fam) = cards[*idx].parsed.family_hash {
                                if buried.contains(fam) {
                                    *idx += 1;
                                    continue;
                                }
                            }
                        }
                        break;
                    }
                }

                let cards = state.cards.lock().unwrap();
                let idx = *state.current_idx.lock().unwrap();
                let revealed = *state.revealed.lock().unwrap();

                if idx >= cards.len() {
                    let started = state.started_at;
                    let ended = Local::now().naive_local();
                    let duration = (ended - started).num_seconds();
                    let total = cards.len();
                    let reviewed = state.reviews.lock().unwrap().len();
                    let pace = if reviewed>0 { duration as f64 / reviewed as f64 } else { 0.0 };
                    let html = format!(r#"<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>hashcards</title><link rel="stylesheet" href="/katex/katex.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css"><script defer src="/katex/katex.js"></script><script defer src="/katex/mhchem.js"></script><script defer src="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js"></script><link rel="stylesheet" href="/style.css"><style>.card-content {{ opacity: 0; }}</style><noscript><style>.card-content {{ opacity: 1; }}</style></noscript></head><body><div class="finished"><h1>Session Completed 🎉</h1><div class="summary">Reviewed {reviewed} cards in {duration} seconds.</div><h2>Session Stats</h2><div class="stats"><table><tbody><tr><td class="key">Total Cards</td><td class="val">{total}</td></tr><tr><td class="key">Cards Reviewed</td><td class="val">{reviewed}</td></tr><tr><td class="key">Started</td><td class="val">{started}</td></tr><tr><td class="key">Finished</td><td class="val">{ended}</td></tr><tr><td class="key">Duration (seconds)</td><td class="val">{duration}</td></tr><tr><td class="key">Pace (s/card)</td><td class="val">{pace:.2}</td></tr></tbody></table></div><div class="shutdown-container"><form action="/" method="post"><input class="shutdown-button" id="shutdown" type="submit" name="action" value="Shutdown" title="Shut down the server"></form></div></div><script src="/script.js"></script></body></html>"#,
                        total=total, reviewed=reviewed, started=started.format("%Y-%m-%d %H:%M:%S"), ended=ended.format("%Y-%m-%d %H:%M:%S"), duration=duration, pace=pace
                    );
                    return Html(html);
                }

                let card = &cards[idx];
                let progress = if cards.len()>0 { (idx as f64 / cards.len() as f64 * 100.0) as usize } else { 0 };

                let (question_html, answer_html, prompt_html) = match &card.parsed.content_internal {
                    CardContentInternal::Basic { question, answer } => {
                        let q_html = markdown_to_html(question);
                        let a_html = markdown_to_html(answer);
                        (q_html, a_html, String::new())
                    },
                    CardContentInternal::Cloze { text, start, end, word: _ } => {
                        let prompt = if revealed {
                            let before = &text[..*start];
                            let word = &text[*start..=*end];
                            let after = &text[*end+1..];
                            format!("<p>{}<span class='cloze-reveal'>{}</span>{}</p>", markdown_to_html(before), markdown_to_html(word), markdown_to_html(after))
                        } else {
                            let before = &text[..*start];
                            let after = &text[*end+1..];
                            format!("<p>{}<span class='cloze'>.............</span>{}</p>", markdown_to_html(before), markdown_to_html(after))
                        };
                        (String::new(), String::new(), prompt)
                    },
                };

                let deck_name = &card.parsed.deck_name;
                let controls_html = if !revealed {
                    r#"<form action="/" method="post"><input id="undo" type="submit" name="action" value="Undo" disabled><div class="spacer"></div><input id="reveal" type="submit" name="action" value="Reveal" title="Show the answer. Shortcut: space."><div class="spacer"></div><input id="end" type="submit" name="action" value="End" title="End the session (changes are saved)"></form>"#.to_string()
                } else {
                    let binary = state.answer_controls == "binary";
                    if binary {
                        r#"<form action="/" method="post"><input id="undo" type="submit" name="action" value="Undo"><div class="spacer"></div><div class="grades"><input id="forgot" type="submit" name="action" value="Forgot" title="Mark card as forgotten. Shortcut: 1."><input id="good" type="submit" name="action" value="Good" title="Mark card as remembered well. Shortcut: 3."></div><div class="spacer"></div><input id="end" type="submit" name="action" value="End" title="End the session (changes are saved)"></form>"#.to_string()
                    } else {
                        r#"<form action="/" method="post"><input id="undo" type="submit" name="action" value="Undo"><div class="spacer"></div><div class="grades"><input id="forgot" type="submit" name="action" value="Forgot" title="Mark card as forgotten. Shortcut: 1."><input id="hard" type="submit" name="action" value="Hard" title="Mark card as difficult. Shortcut: 2."><input id="good" type="submit" name="action" value="Good" title="Mark card as remembered well. Shortcut: 3."><input id="easy" type="submit" name="action" value="Easy" title="Mark card as very easy. Shortcut: 4."></div><div class="spacer"></div><input id="end" type="submit" name="action" value="End" title="End the session (changes are saved)"></form>"#.to_string()
                    }
                };

                let card_content_html = match &card.parsed.content_internal {
                    CardContentInternal::Basic { .. } => {
                        format!(r#"<div class="question rich-text">{}</div><div class="answer rich-text">{}</div>"#, question_html, if revealed { answer_html } else { String::new() })
                    },
                    CardContentInternal::Cloze { .. } => {
                        format!(r#"<div class="prompt rich-text">{}</div>"#, prompt_html)
                    },
                };

                let html = format!(r#"<!DOCTYPE html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>hashcards</title><link rel="stylesheet" href="/katex/katex.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/styles/github.min.css"><script defer src="/katex/katex.js"></script><script defer src="/katex/mhchem.js"></script><script defer src="https://cdnjs.cloudflare.com/ajax/libs/highlight.js/11.9.0/highlight.min.js"></script><link rel="stylesheet" href="/style.css"><style>.card-content {{ opacity: 0; }}</style><noscript><style>.card-content {{ opacity: 1; }}</style></noscript></head><body><div class="root"><div class="header"><div class="progress-bar"><div class="progress-fill" style="width: {progress}%;"></div></div></div><div class="card-container"><div class="card"><div class="card-header"><h1>{deck}</h1></div><div class="card-content">{content}</div></div></div><div class="controls">{controls}</div></div><script src="/script.js"></script></body></html>"#,
                    progress=progress, deck=deck_name, content=card_content_html, controls=controls_html
                );
                Html(html)
            }

            async fn root_post(State(state): State<Arc<AppState>>, Form(form): Form<ActionForm>) -> impl IntoResponse {
                let action = form.action;
                match action.as_str() {
                    "Reveal" => {
                        *state.revealed.lock().unwrap() = true;
                    },
                    "Undo" => {
                        let mut reviews = state.reviews.lock().unwrap();
                        if let Some((hash, _, _, _, _, _, _, _)) = reviews.pop() {
                            // Rebuild buried set
                            let mut buried = state.buried_families.lock().unwrap();
                            buried.clear();
                            let cards = state.cards.lock().unwrap();
                            for (rev_hash, _, _, _, _, _, _, _) in reviews.iter() {
                                for card in cards.iter() {
                                    if card.parsed.hash == *rev_hash {
                                        if let Some(ref fam) = card.parsed.family_hash {
                                            buried.insert(fam.clone());
                                        }
                                    }
                                }
                            }
                        }
                        let mut idx = state.current_idx.lock().unwrap();
                        if *idx > 0 {
                            *idx -= 1;
                        }
                        *state.revealed.lock().unwrap() = false;
                    },
                    "Forgot" | "Hard" | "Good" | "Easy" => {
                        let mut cards = state.cards.lock().unwrap();
                        let mut idx = state.current_idx.lock().unwrap();
                        if *idx < cards.len() {
                            let card = &mut cards[*idx];
                            let now = Local::now().naive_local();
                            let t_days = if let Some(last) = card.last_reviewed {
                                (now.date() - last.date()).num_days() as f64
                            } else {
                                0.0
                            };
                            let (new_stab, new_diff, interval_raw, interval_days, due_date) = compute_fsrs(
                                card.stability,
                                card.difficulty,
                                t_days,
                                &action,
                            );
                            card.stability = Some(new_stab);
                            card.difficulty = Some(new_diff);
                            card.interval_days = Some(interval_days);
                            card.due_date = Some(due_date);
                            card.review_count += 1;
                            card.last_reviewed = Some(now);
                            if state.bury_siblings {
                                if let Some(ref fam) = card.parsed.family_hash {
                                    let mut buried = state.buried_families.lock().unwrap();
                                    buried.insert(fam.clone());
                                }
                            }
                            let mut reviews = state.reviews.lock().unwrap();
                            let reviewed_at_str = now.format("%Y-%m-%dT%H:%M:%S%.3f").to_string();
                            reviews.push((card.parsed.hash.clone(), action.clone(), new_stab, new_diff, interval_raw, interval_days, due_date.format("%Y-%m-%d").to_string(), reviewed_at_str));
                            *idx += 1;
                            *state.revealed.lock().unwrap() = false;
                        }
                    },
                    "End" => {
                        // Save session to DB
                        let reviews = state.reviews.lock().unwrap().clone();
                        let session_id = state.session_id;
                        let started_at = state.started_at;
                        let ended_at = Local::now().naive_local();
                        let started_str = started_at.format("%Y-%m-%dT%H:%M:%S%.3f").to_string();
                        let ended_str = ended_at.format("%Y-%m-%dT%H:%M:%S%.3f").to_string();

                        // Update DB
                        if let Ok(conn) = Connection::open(db_path(&state.collection_dir)) {
                            let _ = ensure_db(&conn);
                            let _ = conn.execute("UPDATE sessions SET ended_at=?1 WHERE session_id=?2", params![ended_str, session_id]);
                            for (hash, grade, stab, diff, int_raw, int_days, due_date, reviewed_at) in reviews.iter() {
                                let _ = conn.execute(
                                    "INSERT INTO reviews (session_id, card_hash, reviewed_at, grade, stability, difficulty, interval_raw, interval_days, due_date) VALUES (?1,?2,?3,?4,?5,?6,?7,?8,?9)",
                                    params![session_id, hash, reviewed_at, grade.to_lowercase(), stab, diff, int_raw, int_days, due_date],
                                );
                                let _ = conn.execute(
                                    "UPDATE cards SET last_reviewed_at=?1, stability=?2, difficulty=?3, interval_raw=?4, interval_days=?5, due_date=?6, review_count=review_count+1 WHERE card_hash=?7",
                                    params![reviewed_at, stab, diff, int_raw, int_days, due_date, hash],
                                );
                            }
                        }

                        let mut idx = state.current_idx.lock().unwrap();
                        let cards_len = state.cards.lock().unwrap().len();
                        *idx = cards_len;
                    },
                    "Shutdown" => {
                        // Save as End
                        let reviews = state.reviews.lock().unwrap().clone();
                        let session_id = state.session_id;
                        let started_at = state.started_at;
                        let ended_at = Local::now().naive_local();
                        let ended_str = ended_at.format("%Y-%m-%dT%H:%M:%S%.3f").to_string();
                        if let Ok(conn) = Connection::open(db_path(&state.collection_dir)) {
                            let _ = ensure_db(&conn);
                            let _ = conn.execute("UPDATE sessions SET ended_at=?1 WHERE session_id=?2", params![ended_str, session_id]);
                            for (hash, grade, stab, diff, int_raw, int_days, due_date, reviewed_at) in reviews.iter() {
                                let _ = conn.execute(
                                    "INSERT INTO reviews (session_id, card_hash, reviewed_at, grade, stability, difficulty, interval_raw, interval_days, due_date) VALUES (?1,?2,?3,?4,?5,?6,?7,?8,?9)",
                                    params![session_id, hash, reviewed_at, grade.to_lowercase(), stab, diff, int_raw, int_days, due_date],
                                );
                                let _ = conn.execute(
                                    "UPDATE cards SET last_reviewed_at=?1, stability=?2, difficulty=?3, interval_raw=?4, interval_days=?5, due_date=?6, review_count=review_count+1 WHERE card_hash=?7",
                                    params![reviewed_at, stab, diff, int_raw, int_days, due_date, hash],
                                );
                            }
                        }
                        // Signal shutdown via special header? We'll just exit process after response? For simplicity, we will not shutdown server here, but main will handle after request?
                        // We'll set current idx to end
                        let mut idx = state.current_idx.lock().unwrap();
                        let cards_len = state.cards.lock().unwrap().len();
                        *idx = cards_len;
                        // We need to shutdown axum server. We can use a oneshot channel, but for simplicity, we will just return redirect and let a background task shutdown after delay
                        tokio::spawn(async {
                            tokio::time::sleep(tokio::time::Duration::from_millis(100)).await;
                            std::process::exit(0);
                        });
                    },
                    _ => {
                        return (StatusCode::UNPROCESSABLE_ENTITY, format!("Failed to deserialize form body: action: unknown variant `{}`, expected one of `Reveal`, `Undo`, `End`, `Forgot`, `Hard`, `Good`, `Easy`, `Shutdown`", action)).into_response();
                    },
                }
                axum::response::Redirect::to("/").into_response()
            }

