            async fn file_handler(State(state): State<Arc<AppState>>, AxumPath(file_path): AxumPath<String>) -> impl IntoResponse {
                // file_path is like "test.mp3" or "thetempest.webp"
                // Resolve relative to collection dir, ensuring inside collection and exists, and is file
                let collection_dir = &state.collection_dir;
                let requested = collection_dir.join(&file_path);
                // Canonicalize check
                let canon = match std::fs::canonicalize(&requested) {
                    Ok(p) => p,
                    Err(_) => return (StatusCode::NOT_FOUND, "Not Found").into_response(),
                };
                let dir_canon = match std::fs::canonicalize(collection_dir) {
                    Ok(p) => p,
                    Err(_) => return (StatusCode::NOT_FOUND, "Not Found").into_response(),
                };
                if !canon.starts_with(dir_canon) {
                    return (StatusCode::NOT_FOUND, "Not Found").into_response();
                }
                if !canon.is_file() {
                    return (StatusCode::NOT_FOUND, "Not Found").into_response();
                }
                // Guess mime
                let mime = mime_guess::from_path(&canon).first_or_octet_stream();
                let data = match std::fs::read(&canon) {
                    Ok(d) => d,
                    Err(_) => return (StatusCode::NOT_FOUND, "Not Found").into_response(),
                };
                ([(header::CONTENT_TYPE, mime.as_ref().to_string())], data).into_response()
            }

