                .route("/katex/fonts/:font", get(katex_font_handler))
                .route("/file/:file", get(file_handler))
                .with_state(app_state);

            let listener = tokio::net::TcpListener::bind(format!("{}:{}", host, port)).await.unwrap();
            println!("Serving on http://{}:{}/", host, port);
            if open_browser.to_lowercase() == "true" {
                let url = format!("http://{}:{}/", host, port);
                let _ = std::process::Command::new("xdg-open").arg(&url).spawn();
                let _ = std::process::Command::new("open").arg(&url).spawn();
            }
            axum::serve(listener, app).await.unwrap();

            Ok::<(), Box<dyn std::error::Error>>(())
        },
        Commands::Check { directory } => {
            let collection_dir = directory.unwrap_or_else(|| std::env::current_dir().unwrap());
            if !collection_dir.exists() {
                eprintln!("hashcards: error: directory does not exist.");
                std::process::exit(1);
            }
            let parsed = match parse_collection(&collection_dir) {
                Ok(c) => c,
                Err(e) => {
                    eprintln!("hashcards: error: {}", e);
                    std::process::exit(1);
                }
            };
            if let Err(e) = check_media(&collection_dir, &parsed) {
                eprintln!("hashcards: error: {}", e);
                std::process::exit(1);
            }
            println!("ok");
            Ok(())
        },
        Commands::Stats { directory, format } => {
            let collection_dir = directory.unwrap_or_else(|| std::env::current_dir().unwrap());
            if !collection_dir.exists() {
                eprintln!("hashcards: error: directory does not exist.");
                std::process::exit(1);
            }
            let parsed = match parse_collection(&collection_dir) {
                Ok(c) => c,
                Err(e) => {
                    eprintln!("hashcards: error: {}", e);
                    std::process::exit(1);
                }
            };
            let cards_in_deck = parsed.len();
            let db_p = db_path(&collection_dir);
            let mut cards_in_db = 0;
            let mut reviewed_today = 0;
            if db_p.exists() {
                if let Ok(conn) = Connection::open(&db_p) {
                    let _ = ensure_db(&conn);
                    if let Ok(mut stmt) = conn.prepare("SELECT COUNT(*) FROM cards") {
                        if let Ok(cnt) = stmt.query_row([], |row| row.get::<_, i64>(0)) {
                            cards_in_db = cnt as usize;
                        }
                    }
                    let today_str = Local::now().naive_local().format("%Y-%m-%d").to_string();
                    if let Ok(mut stmt) = conn.prepare("SELECT COUNT(*) FROM reviews WHERE substr(reviewed_at,1,10)=?1") {
                        if let Ok(cnt) = stmt.query_row(params![today_str], |row| row.get::<_, i64>(0)) {
                            reviewed_today = cnt as usize;
                        }
                    }
                }
            }
            let tex_macro_count = count_tex_macros(&collection_dir);
            if format == "json" {
                let stats = StatsJson {
                    cardsInDeckCount: cards_in_deck,
                    cardsInDbCount: cards_in_db,
                    texMacroCount: tex_macro_count,
                    cardsReviewedTodayCount: reviewed_today,
                };
                println!("{}", serde_json::to_string_pretty(&stats).unwrap());
            } else if format == "html" {
                eprintln!("HTML output is not implemented yet.");
                std::process::exit(1);
            } else {
                eprintln!("Unknown format");
                std::process::exit(1);
            }
            Ok(())
        },
        Commands::Orphans { command } => {
            match command {
                OrphansCommands::List { directory } => {
                    let collection_dir = directory.unwrap_or_else(|| std::env::current_dir().unwrap());
                    if !collection_dir.exists() {
                        eprintln!("hashcards: error: directory does not exist.");
                        std::process::exit(1);
                    }
                    let parsed = match parse_collection(&collection_dir) {
                        Ok(c) => c,
                        Err(e) => {
                            eprintln!("hashcards: error: {}", e);
                            std::process::exit(1);
                        }
                    };
                    let deck_hashes: HashSet<String> = parsed.iter().map(|c| c.hash.clone()).collect();
                    let db_p = db_path(&collection_dir);
                    if !db_p.exists() {
                        return Ok(());
                    }
                    let conn = Connection::open(&db_p)?;
                    ensure_db(&conn)?;
                    let mut stmt = conn.prepare("SELECT card_hash FROM cards")?;
                    let rows = stmt.query_map([], |row| row.get::<_, String>(0))?;
                    for hash_res in rows {
                        let hash = hash_res?;
                        if !deck_hashes.contains(&hash) {
                            println!("{}", hash);
                        }
                    }
                    Ok(())
                },
                OrphansCommands::Delete { directory } => {
                    let collection_dir = directory.unwrap_or_else(|| std::env::current_dir().unwrap());
                    if !collection_dir.exists() {
                        eprintln!("hashcards: error: directory does not exist.");
                        std::process::exit(1);
                    }
                    let parsed = match parse_collection(&collection_dir) {
                        Ok(c) => c,
                        Err(e) => {
                            eprintln!("hashcards: error: {}", e);
                            std::process::exit(1);
                        }
                    };
                    let deck_hashes: HashSet<String> = parsed.iter().map(|c| c.hash.clone()).collect();
                    let db_p = db_path(&collection_dir);
                    if !db_p.exists() {
                        return Ok(());
                    }
                    let conn = Connection::open(&db_p)?;
                    ensure_db(&conn)?;
                    let mut stmt = conn.prepare("SELECT card_hash FROM cards")?;
                    let rows = stmt.query_map([], |row| row.get::<_, String>(0))?;
                    let mut orphans: Vec<String> = Vec::new();
                    for hash_res in rows {
                        let hash = hash_res?;
                        if !deck_hashes.contains(&hash) {
                            orphans.push(hash);
                        }
                    }
                    for orphan in &orphans {
                        println!("{}", orphan);
                        conn.execute("DELETE FROM cards WHERE card_hash=?1", params![orphan])?;
                    }
                    Ok(())
                },
            }
        },
        Commands::Export { directory, output } => {
            let collection_dir = directory.unwrap_or_else(|| std::env::current_dir().unwrap());
            if !collection_dir.exists() {
                eprintln!("hashcards: error: directory does not exist.");
                std::process::exit(1);
            }
            let parsed = match parse_collection(&collection_dir) {
                Ok(c) => c,
                Err(e) => {
                    eprintln!("hashcards: error: {}", e);
                    std::process::exit(1);
                }
            };
            let db_p = db_path(&collection_dir);
            let mut performance_map: HashMap<String, Performance> = HashMap::new();
            let mut sessions: Vec<SessionExport> = Vec::new();
            if db_p.exists() {
                if let Ok(conn) = Connection::open(&db_p) {
                    let _ = ensure_db(&conn);
                    if let Ok(mut stmt) = conn.prepare("SELECT card_hash, last_reviewed_at, stability, difficulty, interval_raw, interval_days, due_date, review_count FROM cards") {
                        if let Ok(rows) = stmt.query_map([], |row| {
                            Ok((
                                row.get::<_, String>(0)?,
                                row.get::<_, Option<String>>(1)?,
                                row.get::<_, Option<f64>>(2)?,
                                row.get::<_, Option<f64>>(3)?,
                                row.get::<_, Option<f64>>(4)?,
                                row.get::<_, Option<i64>>(5)?,
                                row.get::<_, Option<String>>(6)?,
                                row.get::<_, i64>(7)?,
                            ))
                        }) {
                            for r in rows {
                                if let Ok((hash, last_rev, stab, diff, int_raw, int_days, due, rev_cnt)) = r {
                                    if rev_cnt>0 {
                                        performance_map.insert(hash, Performance {
                                            lastReviewedAt: last_rev,
                                            stability: stab,
                                            difficulty: diff,
                                            intervalRaw: int_raw,
                                            intervalDays: int_days,
                                            dueDate: due,
                                            reviewCount: Some(rev_cnt),
                                        });
                                    }
                                }
                            }
                        }
                    }
                    if let Ok(mut stmt) = conn.prepare("SELECT session_id, started_at, ended_at FROM sessions ORDER BY session_id") {
                        if let Ok(sess_rows) = stmt.query_map([], |row| {
                            Ok((
                                row.get::<_, i64>(0)?,
                                row.get::<_, String>(1)?,
                                row.get::<_, String>(2)?,
                            ))
                        }) {
                            for sess_res in sess_rows {
                                if let Ok((sid, started, ended)) = sess_res {
                                    let mut revs: Vec<ReviewExport> = Vec::new();
                                    if let Ok(mut rev_stmt) = conn.prepare("SELECT review_id, card_hash, reviewed_at, grade, stability, difficulty, interval_raw, interval_days, due_date FROM reviews WHERE session_id=?1 ORDER BY review_id") {
                                        if let Ok(rev_rows) = rev_stmt.query_map(params![sid], |row| {
                                            Ok(ReviewExport {
                                                reviewId: row.get(0)?,
                                                hash: row.get(1)?,
                                                reviewedAt: row.get(2)?,
                                                grade: row.get::<_, String>(3)?.to_lowercase(),
                                                stability: row.get(4)?,
                                                difficulty: row.get(5)?,
                                                intervalRaw: row.get(6)?,
                                                intervalDays: row.get(7)?,
                                                dueDate: row.get(8)?,
                                            })
                                        }) {
                                            for rev in rev_rows {
                                                if let Ok(r) = rev {
                                                    revs.push(r);
                                                }
                                            }
                                        }
                                    }
                                    sessions.push(SessionExport {
                                        sessionId: sid,
                                        startedAt: started,
                                        endedAt: ended,
                                        reviews: revs,
                                    });
                                }
                            }
                        }
                    }
                }
            }
            let mut export_cards: Vec<ExportCard> = Vec::new();
            for pc in parsed {
                let perf = performance_map.get(&pc.hash).cloned();
                let content = match pc.content_internal {
                    CardContentInternal::Basic { question, answer } => {
                        ExportCardContent {
                            basic: Some(BasicContent { question, answer }),
                            cloze: None,
                        }
                    },
                    CardContentInternal::Cloze { text, start, end, .. } => {
                        ExportCardContent {
                            basic: None,
                            cloze: Some(ClozeContent { text, start, end }),
                        }
                    },
                };
                export_cards.push(ExportCard {
                    hash: pc.hash,
                    familyHash: pc.family_hash,
                    deckName: pc.deck_name,
                    location: pc.location,
                    content,
                    performance: perf,
                });
            }
            let output_data = ExportOutput {
                cards: export_cards,
                sessions,
            };
            let json_str = serde_json::to_string_pretty(&output_data).unwrap();
            if let Some(out_path) = output {
                std::fs::write(out_path, json_str)?;
            } else {
                println!("{}", json_str);
            }
            Ok(())
        },
    }
}
RS
"}

